const size_t DEVANAGARI_ENTRIES_COUNT = sizeof(DEVANAGARI_ENTRIES) / sizeof(DEVANAGARI_ENTRIES[0]);

const std::unordered_map<std::string, std::vector<std::string>>& DevanagariDict::get_map() {
    static std::unordered_map<std::string, std::vector<std::string>> s_map;
    static bool s_init = false;
    if (!s_init) {
        s_map.reserve(DEVANAGARI_ENTRIES_COUNT);
        for (size_t i = 0; i < DEVANAGARI_ENTRIES_COUNT; ++i) {
            auto& vec = s_map[DEVANAGARI_ENTRIES[i].key];
            if (DEVANAGARI_ENTRIES[i].cand1) vec.push_back(DEVANAGARI_ENTRIES[i].cand1);
            if (DEVANAGARI_ENTRIES[i].cand2) vec.push_back(DEVANAGARI_ENTRIES[i].cand2);
            if (DEVANAGARI_ENTRIES[i].cand3) vec.push_back(DEVANAGARI_ENTRIES[i].cand3);
        }
        s_init = true;
    }
    return s_map;
}

